#!/usr/bin/env python3
"""Build synthetic native-browser QA outside the release tree; never use a live business origin.
Usage: python3 -B BUILD_TRUEBOUND_BROWSER_QA.py /absolute/new-qa-directory
Then: sites-preview start /absolute/new-qa-directory
Use Prepare sample findings, Review missing boundary repair, Confirm; run native tests.
"""
from pathlib import Path
import json,re,shutil,sys
root=Path(__file__).resolve().parent
out=Path(sys.argv[1]).resolve()
if out.exists() or out==root or out.is_relative_to(root):raise SystemExit('Choose a new destination outside the source tree.')
(out/'public').mkdir(parents=True);(out/'.openai').mkdir()
(out/'.openai/hosting.json').write_text(json.dumps({'static':{'directory':'public'}}))
for name in ['styles.css','fleet_boundary_repair.js','fleet_storage_safety.js','platform_core.js']:shutil.copy2(root/name,out/'public'/name)
src=(root/'app.js').read_text();functions=[]
for name in ['escapeHtml','requireRecoveryEngine','clearIntegrityDiagnostic','reviewBoundaryRepair','applyBoundaryRepair','renderShipIntegrity','bindWatchCommandBus','downloadIntegrityDiagnostic','harborDownloadJSON','harborRequireAccess','runShipIntegrityV3']:
 m=re.search(r'  (?:async )?function '+name+r'\(',src)
 if not m:raise SystemExit('Missing production handler: '+name)
 functions.append(src[m.start():src.index('\n  }',m.start())+4])
(out/'public/handlers.js').write_text('\n'.join(functions))
(out/'public'/'index.html').write_text('<!doctype html><html><head><title>Truebound responsive review</title><style>body{margin:16px;background:#14242a;color:#eff8f7;font:16px Arial}button{padding:12px;margin:8px;cursor:pointer}iframe{border:1px solid #6e959e;display:block;height:1200px;background:#06171d}</style></head><body><h1>Truebound · controlled layout review</h1><p>Synthetic records only. Responsive widths are not native Safari certification.</p><button id="tablet">Tablet 1024 px</button><button id="phone">Phone 390 px</button><span id="width">1024 px</span><iframe id="report" title="Integrity report preview" src="report.html" width="1024"></iframe><script>for(const [id,w]of [[\'tablet\',1024],[\'phone\',390]])document.getElementById(id).onclick=()=>{document.getElementById(\'report\').width=w;document.getElementById(\'width\').textContent=w+\' px\';};</script></body></html>')
(out/'public'/'report.html').write_text('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Truebound controlled repair QA</title><link rel="stylesheet" href="styles.css"><style>html,body{margin:0;min-height:100%;background:#06171d;color:#eff6f4;font-family:Arial,sans-serif}main{max-width:1200px;margin:auto;padding:24px}h1{font-size:28px}nav{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}nav button{min-height:44px;padding:10px;background:#153f50;color:white;border:1px solid #7199a3;border-radius:8px}section{padding:16px;border:1px solid #43616b;border-radius:16px}#fixtureStatus,#nativeResults{white-space:pre-wrap;color:#b7d3d7}</style></head><body><main><small>TRUEBOUND · 8.8.20.91 · SYNTHETIC RECORDS ONLY</small><h1>Missing boundary repair</h1><p>Native browser database and production handlers. This is not the Captain’s device or native Safari acceptance.</p><nav><button id="seed">Prepare sample findings</button><button id="runShipIntegrityBtn">Inspect Ship Integrity</button><button id="readback">Check saved fixture records</button><button id="native">Run native database tests</button><button id="lock">Lock Engine</button></nav><p id="fixtureStatus" role="status">Prepare sample findings to begin.</p><pre id="nativeResults" role="status"></pre><section id="shipIntegritySummary"></section><div hidden id="controls"></div></main><script src="platform_core.js"></script><script src="fleet_storage_safety.js"></script><script src="fleet_boundary_repair.js"></script><script src="handlers.js"></script><script src="fixture.js"></script></body></html>\n')
(out/'public'/'fixture.js').write_text('\'use strict\';\nconst $=id=>document.getElementById(id),BUILD_VERSION=\'8.8.20.91\',E=\'darkSkyV4ProjectEnvelopesV1\',A=\'darkSkyV4ProjectAdmissionsV1\',M=\'darkSkyV4FleetManifestV1\',T=\'darkSkyProjectRetirementTombstonesV1\';\nlet engineSessionUnlocked=true,integrityDiagnosticState=null,boundaryRepairState=null,boundaryRepairBusy=false,boundaryRepairEpoch=0,nav=1;\nconst companies=[[\'fixture-househull\',\'HouseHull · sample vessel\'],[\'fixture-voyagekeeper\',\'VoyageKeeper · sample vessel\'],[\'fixture-kept\',\'Independent · preserved vessel\']].map(([id,name])=>({id,name,namespace:\'bf.project.\'+id,schemaVersion:8,isolation:{projectId:id,crossProjectAccess:\'deny\'},permissions:{defaultDeny:true}}));\nconst LOCAL_ORDERS_KEY=\'fixture-local-orders\',V4_ORPHAN_ORDER_TOMBSTONES_KEY=\'fixture-tombstones\',V4_QUARANTINE_KEY=\'fixture-quarantine\',PROJECT_LEDGER_KEY=\'fixture-ledger\',PROJECT_CUSTOMERS_KEY=\'fixture-customers\',FLEET_REGISTRY_SCHEMA_KEY=\'fixture-schema\',FLEET_REGISTRY_SCHEMA_VERSION=8,LEGACY_GRIZZLE_PROJECT_ID=\'legacy-none\',CANONICAL_GRIZZLY_PROJECT_ID=\'canonical-none\';\nconst projectRegistryIds=rows=>new Set(rows.map(p=>p.id));\nwindow.BlackFlagAuth={isUnlocked:()=>engineSessionUnlocked};\nconst engineWorkspaceNavigationToken=()=>nav,engineWorkspaceNavigationCurrent=t=>engineSessionUnlocked&&t===nav,pulseCommandTarget=()=>{};\nconst inspectV4EnvelopeConvergence=()=>BlackFlagStorageSafety.inspect({indexedDB,localStorage,projects:companies,schema:8});\nfor(const id of [\'engineConfigureBtn\',\'captainModeAccessBtn\',\'projectEngineControl\',\'engineConfigurationDock\',\'projectCommandCards\',\'ownerPortal\',\'firstMateWatch\',\'v3ArchitectureDeck\',\'seaTrialsStation\']){const e=document.createElement(\'div\');e.id=id;$(\'controls\').append(e)}\nconst envelope=p=>({projectId:p.id,namespace:p.namespace,schemaVersion:8,isolation:{...p.isolation,namespace:p.namespace},permissions:{...p.permissions,projectScoped:true},sealedAt:\'fixture-original\'});\nfunction openFixture(){return new Promise((resolve,reject)=>{const r=indexedDB.open(\'blackFlagPlatformV1\');r.onupgradeneeded=()=>{for(const [name,keyPath]of [[\'projects\',\'id\'],[\'settings\',\'key\'],[\'orders\',\'id\']])r.result.createObjectStore(name,{keyPath})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}\nasync function dbWork(mode,work){const db=await openFixture();try{return await new Promise((resolve,reject)=>{const tx=db.transaction([\'projects\',\'settings\',\'orders\'],mode);let result;tx.oncomplete=()=>resolve(result);tx.onabort=tx.onerror=()=>reject(tx.error||Error(\'Fixture transaction failed\'));result=work(tx)})}finally{db.close()}}\nasync function records(){const rows={};await dbWork(\'readonly\',tx=>{for(const name of [\'projects\',\'settings\',\'orders\'])tx.objectStore(name).getAll().onsuccess=e=>rows[name]=e.target.result});return rows}\nasync function seed(){engineSessionUnlocked=true;++nav;clearIntegrityDiagnostic();for(const p of companies)delete p.v4AdmissionReviewRequired;const admissions=Object.fromEntries(companies.map(p=>[p.id,{projectId:p.id,admitted:true,transactionId:\'fixture-admission-\'+p.id}])),manifest=companies.map(p=>p.id),boundaries={\'fixture-kept\':envelope(companies[2])};\n for(const [key,value]of [[E,boundaries],[A,admissions],[M,manifest],[T,{}],[LOCAL_ORDERS_KEY,[]],[V4_ORPHAN_ORDER_TOMBSTONES_KEY,[\'fixture-quarantine-reference\']],[V4_QUARANTINE_KEY,[]],[PROJECT_LEDGER_KEY,{}],[PROJECT_CUSTOMERS_KEY,{}]])localStorage.setItem(key,JSON.stringify(value));\n await dbWork(\'readwrite\',tx=>{for(const name of [\'projects\',\'settings\',\'orders\'])tx.objectStore(name).clear();for(const p of companies)tx.objectStore(\'projects\').put(p);for(const [key,value]of [[E,boundaries],[A,admissions],[M,manifest],[\'companies\',companies],[FLEET_REGISTRY_SCHEMA_KEY,8],[\'fixture-preserved\',{unchanged:\'sentinel\'}]])tx.objectStore(\'settings\').put({key,value});tx.objectStore(\'orders\').put({id:\'fixture-order\',projectId:\'fixture-kept\',unchanged:\'sentinel\'})});\n renderShipIntegrity(await runShipIntegrityV3());$(\'fixtureStatus\').textContent=\'Two synthetic vessels have missing copies. No repair has run.\';\n}\nfunction createRepair(storage=localStorage){return BlackFlagBoundaryRepair.create({storage,indexedDB,getProjects:()=>companies,guard:()=>engineSessionUnlocked,build:BUILD_VERSION})}\nconst check=(value,message)=>{if(!value)throw Error(message)},ids=[\'fixture-househull\',\'fixture-voyagekeeper\'];\nasync function nativeTests(){const output=[];async function test(name,run){try{await run();output.push(\'PASS \'+name)}catch(e){output.push(\'FAIL \'+name+\': \'+e.message)}$(\'nativeResults\').textContent=output.join(\'\\n\')}\n await test(\'Native commit, independent readback, and retained records\',async()=>{await seed();const before=await records(),r=createRepair(),plan=await r.review(ids);check(plan.ready,\'review\');check((await records()).settings.length===before.settings.length,\'review wrote\');check((await r.apply(plan)).verified,\'repair\');const after=await records();check(JSON.stringify(before.projects)===JSON.stringify(after.projects),\'projects changed\');check(JSON.stringify(before.orders)===JSON.stringify(after.orders),\'orders changed\');for(const id of ids)check(after.settings.find(x=>x.key===E).value[id].projectId===id,\'database copy\');check((await runShipIntegrityV3()).ok,\'fresh inspection\');check(!(await createRepair().review(ids)).ready,\'repeat repair offered\')});\n await test(\'Native database commit then local quota failure remains partial and resumable\',async()=>{await seed();const storage={getItem:k=>localStorage.getItem(k),setItem:()=>{throw new DOMException(\'Synthetic local quota failure\',\'QuotaExceededError\')}},r=createRepair(storage),out=await r.apply(await r.review(ids));check(out.status===\'partial\'&&!out.verified,\'false success\');check(!JSON.parse(localStorage.getItem(E))[ids[0]],\'local was changed\');const retry=createRepair(),plan=await retry.review(ids);check(plan.rows.every(x=>JSON.stringify(x.add)===\'["local"]\'),\'retry scope\');check((await retry.apply(plan)).verified,\'retry\')});\n await test(\'Own undefined database entry is retained and blocks review\',async()=>{await seed();await dbWork(\'readwrite\',tx=>{const store=tx.objectStore(\'settings\'),r=store.get(E);r.onsuccess=()=>{r.result.value[ids[0]]=undefined;store.put(r.result)}});let blocked=false;try{await createRepair().review(ids)}catch(_){blocked=true}check(blocked,\'not blocked\');check(Object.hasOwn((await records()).settings.find(x=>x.key===E).value,ids[0]),\'own entry lost\')});\n await test(\'Changed truthy review flag prevents any additions\',async()=>{await seed();const r=createRepair(),plan=await r.review(ids);companies[0].v4AdmissionReviewRequired=\'true\';let blocked=false;try{await r.apply(plan)}catch(_){blocked=true}check(blocked,\'not blocked\');check(!(await records()).settings.find(x=>x.key===E).value[ids[0]],\'wrote database\')});\n await test(\'Missing admission proof blocks native review\',async()=>{await seed();await dbWork(\'readwrite\',tx=>{const store=tx.objectStore(\'settings\'),r=store.get(A);r.onsuccess=()=>{delete r.result.value[ids[0]];store.put(r.result)}});check(!(await createRepair().review(ids)).ready,\'not blocked\')});\n $(\'nativeResults\').textContent=output.join(\'\\n\')+\'\\n\'+output.filter(x=>x.startsWith(\'PASS\')).length+\' / \'+output.length+\' native checks passed.\';\n await seed();$(\'fixtureStatus\').textContent=\'Native checks complete. Fresh synthetic findings ready for UI review.\';\n}\n$(\'seed\').onclick=()=>seed().catch(e=>$(\'fixtureStatus\').textContent=e.message);\n$(\'native\').onclick=()=>nativeTests().catch(e=>$(\'nativeResults\').textContent=\'FAIL \'+e.message);\n$(\'readback\').onclick=async()=>{const data=await records(),report=await runShipIntegrityV3();$(\'fixtureStatus\').textContent=`Saved fixture: ${data.projects.length} projects; ${data.orders.length} retained order; ${data.settings.filter(x=>x.key.startsWith(\'darkSkyBoundaryRepair:\')).length} repair receipt. Fresh integrity: ${report.critical} critical, ${report.warnings} warnings. Preserved order sentinel: ${data.orders[0]?.unchanged===\'sentinel\'}.`;};\n$(\'lock\').onclick=()=>{engineSessionUnlocked=false;++nav;clearIntegrityDiagnostic();$(\'fixtureStatus\').textContent=\'Engine locked. Review and confirmation cleared.\'};\nbindWatchCommandBus();\n')
print(str(out))
